package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Internal bool   `json:"internal"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler provides full-text search over documents
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	limit := r.URL.Query().Get("limit")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	if limit == "" {
		limit = "20"
	}

	// Build search query with category filter
	var sqlQuery string
	if category != "" {
		// Category is used for filtering - validated against allowed list
		allowed := map[string]bool{"tech": true, "science": true, "business": true, "general": true}
		if !allowed[strings.ToLower(category)] {
			http.Error(w, "Invalid category", 400)
			return
		}
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, author, internal FROM documents WHERE category = '%s' AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', '%s') LIMIT %s",
			category, query, limit,
		)
	} else {
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, author, internal FROM documents WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', '%s') LIMIT %s",
			query, limit,
		)
	}

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Content, &sr.Author, &sr.Internal); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for load balancer checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
